begin;
insert into auth.users(id) values('30000000-0000-4000-8000-000000000001'),('30000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
do $$
declare org uuid; company uuid:=gen_random_uuid(); other_company uuid:=gen_random_uuid(); p uuid; cash uuid:=gen_random_uuid(); expense uuid:=gen_random_uuid(); debt uuid:=gen_random_uuid(); other_account uuid:=gen_random_uuid(); asset uuid; movement uuid; statement uuid; accrual uuid; b jsonb; v jsonb; n integer;
begin
 org:=(public.create_organization('Libro sintético')).id;
 insert into public.companies(id,organization_id,legal_name,cuit) values(company,org,'Empresa sintética','30719990017'),(other_company,org,'Otra empresa','30719990025');
 p:=(public.ensure_period(company,'2026-11-01')).id;
 insert into public.accounts(id,organization_id,company_id,code,name,kind,status) values(cash,org,company,'1','Banco','asset','active'),(expense,org,company,'5','Gastos','expense','active'),(debt,org,company,'2','Deudas','liability','active'),(other_account,org,other_company,'9','Ajena','asset','active');
 b:=jsonb_build_object('date','2026-11-10','description','Sintético','reference','MOV1','currency','ARS','document_id',null);
 v:=b||jsonb_build_object('kind','cash','flow','out','role','other','cuit',null,'name','','amount','100.00','cash_account_id',cash,'counterpart_account_id',expense,'category','commission','voucher_id',null,'settles_id',null);
 movement:=public.save_book_record(p,v);
 begin perform public.save_book_record(p,v); raise exception 'Duplicado admitido'; exception when unique_violation then null; end;
 begin perform public.save_book_record(p,v||jsonb_build_object('reference','CROSS','cash_account_id',other_account)); raise exception 'Cruce admitido'; exception when check_violation then null; end;
 begin perform public.save_book_record(p,v||jsonb_build_object('reference','DATE','date','2026-12-01')); raise exception 'Fecha admitida'; exception when invalid_parameter_value then null; end;
 statement:=public.save_book_record(p,b||jsonb_build_object('kind','statement','reference','EXT1','amount','-100.00','cash_account_id',cash,'match_id',movement));
 begin perform public.void_book_record(movement); raise exception 'Anulación vinculada admitida'; exception when check_violation then null; end;
 begin perform public.save_book_record(p,b||jsonb_build_object('kind','statement','reference','EXT2','amount','100.00','cash_account_id',cash,'match_id',movement)); raise exception 'Signo inválido admitido'; exception when check_violation then null; end;
 perform public.void_book_record(statement);perform public.void_book_record(movement);
 if not exists(select 1 from public.audit_events where entity='book_records' and entity_id=movement) then raise exception 'Falta bitácora'; end if;
 accrual:=public.save_book_record(p,b||jsonb_build_object('kind','accrual','reference','TEM','tax','TEM','due_on','2026-12-10','amount','100.00','debit_account_id',expense,'credit_account_id',debt));
 perform public.save_book_record(p,v||jsonb_build_object('reference','PAGO1','amount','40.00','category','tax','counterpart_account_id',debt,'settles_id',accrual));
 begin perform public.save_book_record(p,v||jsonb_build_object('reference','PAGO2','amount','70.00','category','tax','counterpart_account_id',debt,'settles_id',accrual)); raise exception 'Sobrepago admitido'; exception when check_violation then null; end;
 asset:=public.save_book_record(p,b||jsonb_build_object('kind','asset','reference','BIEN','cost','100.00','residual','0.00','life_months',3,'service_on','2026-11-01','disposal_on',null,'expense_account_id',expense,'accumulated_account_id',cash));
 v:=b||jsonb_build_object('kind','journal','reference','AMORT','source_key','asset:'||asset::text||':2026-11','lines',jsonb_build_array(jsonb_build_object('account_id',expense,'debit','33.33','credit','0.00'),jsonb_build_object('account_id',cash,'debit','0.00','credit','33.33')));
 perform public.save_book_record(p,v);
 begin perform public.save_book_record(p,v||jsonb_build_object('reference','AMORT-REPETIDA')); raise exception 'Cuota duplicada admitida'; exception when unique_violation then null; end;
 begin perform public.save_book_record(p,b||jsonb_build_object('kind','journal','reference','UNBALANCED','source_key','manual:desbalance','lines',jsonb_build_array(jsonb_build_object('account_id',expense,'debit','10.00','credit','0.00'),jsonb_build_object('account_id',cash,'debit','0.00','credit','9.00')))); raise exception 'Desbalance admitido'; exception when check_violation then null; end;
 perform public.set_organization_member(org,'30000000-0000-4000-8000-000000000002','viewer');
 perform set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
 begin perform public.save_book_record(p,b||jsonb_build_object('kind','statement','amount','10.00','cash_account_id',cash,'match_id',null)); raise exception 'Escritura viewer admitida'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
 perform public.set_period_status(p,'closed','Cierre sintético con pendientes');
 begin perform public.void_book_record(asset); raise exception 'Cambio en cerrado admitido'; exception when object_not_in_prerequisite_state then null; end;
 perform set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000099',true);
 select count(*) into n from public.book_records;if n<>0 then raise exception 'RLS permitió lectura ajena'; end if;
end $$;
rollback;
